from __future__ import annotations

from typing import Any

from user_store import UserStore


def create_user(payload: dict[str, Any], store: UserStore) -> dict[str, Any]:
    email = payload["email"].strip().lower()
    name = payload["name"].strip()
    age = int(payload["age"])
    plan = payload.get("plan", "free").strip().lower()

    if "@" not in email or "." not in email:
        return {"ok": False, "reason": "invalid_email"}
    if len(name) < 2:
        return {"ok": False, "reason": "invalid_name"}
    if age < 13:
        return {"ok": False, "reason": "age_restricted"}
    if plan not in {"free", "pro", "team"}:
        return {"ok": False, "reason": "invalid_plan"}
    if store.exists(email):
        return {"ok": False, "reason": "already_exists"}

    user = {"email": email, "name": name, "age": age, "plan": plan}
    store.save(user)
    return {"ok": True, "reason": "created", "user": user}


def create_users_batch(payloads: list[dict[str, Any]], store: UserStore) -> dict[str, Any]:
    results: list[dict[str, Any]] = []
    success = 0
    failed = 0
    for payload in payloads:
        result = create_user(payload, store)
        results.append(result)
        if result.get("ok"):
            success += 1
        else:
            failed += 1
    return {"success": success, "failed": failed, "results": results}


def create_user_for_api(payload: dict[str, Any], store: UserStore) -> dict[str, Any]:
    result = create_user(payload, store)
    if result.get("ok"):
        return {"status": 201, "body": result}
    return {"status": 400, "body": result}


def healthcheck() -> dict[str, str]:
    return {"status": "ok"}


def summarize_batch(result: dict[str, Any]) -> dict[str, int]:
    return {
        "success": int(result.get("success", 0)),
        "failed": int(result.get("failed", 0)),
    }

