from __future__ import annotations

from typing import Any


class UserStore:
    def __init__(self) -> None:
        self._users: dict[str, dict[str, Any]] = {}

    def save(self, user: dict[str, Any]) -> None:
        email = str(user.get("email", "")).strip().lower()
        if not email:
            raise ValueError("email required")
        self._users[email] = {
            "email": email,
            "name": str(user.get("name", "")).strip(),
            "age": int(user.get("age", 0)),
            "plan": str(user.get("plan", "free")).strip().lower(),
        }

    def exists(self, email: str) -> bool:
        key = email.strip().lower()
        return bool(key) and key in self._users

    def get(self, email: str) -> dict[str, Any] | None:
        key = email.strip().lower()
        if not key:
            return None
        item = self._users.get(key)
        if item is None:
            return None
        return dict(item)

    def count(self) -> int:
        return len(self._users)

    def list_all(self) -> list[dict[str, Any]]:
        return [dict(item) for item in self._users.values()]

    def clear(self) -> None:
        self._users.clear()

    def snapshot(self) -> dict[str, dict[str, Any]]:
        return {key: dict(value) for key, value in self._users.items()}

    def remove(self, email: str) -> bool:
        key = email.strip().lower()
        if not key:
            return False
        if key in self._users:
            del self._users[key]
            return True
        return False

    def keys(self) -> list[str]:
        return sorted(self._users.keys())

